lemmas.pullˡ:
{b.Y = A : Obj} {c.Y = B : Obj} {a = i₁ : A ⇒ B} {c.X = j : Obj}
{b = k : j ⇒ A} {c : j ⇒ B} →
i₁ ∘ k ≈ c → {f.X : Obj} {f = f₁ : f.X ⇒ j} → i₁ ∘ k ∘ f₁ ≈ c ∘ f₁

lemmas.assoc:
{A B : Obj} {C = i₁ : Obj} {D = j : Obj} {f = k : A ⇒ B}
{g = c : B ⇒ i₁} {h = h₁ : i₁ ⇒ j} →
(h₁ ∘ c) ∘ k ≈ h₁ ∘ c ∘ k

